var n int
var G [][]byte
var memo map[uint64]int

func chToVal(ch byte, first bool) int {
	if ch == 'a' {
		if first {
			return 1
		}
		return -1
	}
	if ch == 'b' {
		if first {
			return -1
		}
		return 1
	}
	return 0
}

func hashState(sum int, R []bool) uint64 {
	h := uint64(sum)
	for _, b := range R {
		h = (h << 1) | uint64(b2u(b))
	}
	return h
}

func b2u(b bool) uint64 {
	if b {
		return 1
	}
	return 0
}

